CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name varchar(160) NOT NULL, code varchar(30) UNIQUE NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE branches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), name varchar(160) NOT NULL, code varchar(30) NOT NULL, UNIQUE (organization_id, code));
CREATE TABLE fiscal_periods (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), title varchar(80) NOT NULL, starts_on date NOT NULL, ends_on date NOT NULL, status varchar(20) NOT NULL DEFAULT 'open', CHECK (ends_on > starts_on));
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), username varchar(80) UNIQUE NOT NULL, password_hash text NOT NULL, display_name varchar(160) NOT NULL, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), name varchar(100) NOT NULL, UNIQUE (organization_id, name));
CREATE TABLE permissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code varchar(120) UNIQUE NOT NULL, description varchar(250) NOT NULL);
CREATE TABLE user_roles (user_id uuid REFERENCES users(id) ON DELETE CASCADE, role_id uuid REFERENCES roles(id) ON DELETE CASCADE, PRIMARY KEY (user_id, role_id));
CREATE TABLE role_permissions (role_id uuid REFERENCES roles(id) ON DELETE CASCADE, permission_id uuid REFERENCES permissions(id) ON DELETE CASCADE, PRIMARY KEY (role_id, permission_id));
CREATE TABLE sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, organization_id uuid NOT NULL REFERENCES organizations(id), token_hash text UNIQUE NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE workflow_instances (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), entity_type varchar(80) NOT NULL, entity_id uuid NOT NULL, status varchar(30) NOT NULL DEFAULT 'pending', current_step smallint NOT NULL DEFAULT 1, created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE workflow_actions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workflow_id uuid NOT NULL REFERENCES workflow_instances(id) ON DELETE CASCADE, actor_id uuid NOT NULL REFERENCES users(id), action varchar(30) NOT NULL, note text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), code varchar(40) NOT NULL, title varchar(160) NOT NULL, parent_id uuid REFERENCES accounts(id), level smallint NOT NULL DEFAULT 1, UNIQUE (organization_id, code));
CREATE TABLE journal_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), fiscal_period_id uuid NOT NULL REFERENCES fiscal_periods(id), number bigint NOT NULL, description varchar(500) NOT NULL, source_type varchar(80), source_id uuid, status varchar(20) NOT NULL DEFAULT 'draft', posted_by uuid REFERENCES users(id), posted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (organization_id, fiscal_period_id, number));
CREATE TABLE journal_lines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), journal_entry_id uuid NOT NULL REFERENCES journal_entries(id) ON DELETE CASCADE, account_id uuid NOT NULL REFERENCES accounts(id), debit numeric(20,2) NOT NULL DEFAULT 0, credit numeric(20,2) NOT NULL DEFAULT 0, cost_center varchar(80), project_id uuid, CHECK (debit >= 0 AND credit >= 0 AND NOT (debit > 0 AND credit > 0)));
CREATE TABLE domain_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), module varchar(60) NOT NULL, event_type varchar(100) NOT NULL, aggregate_id uuid, payload jsonb NOT NULL, created_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), actor_id uuid REFERENCES users(id), action varchar(30) NOT NULL, entity_type varchar(80) NOT NULL, entity_id uuid, before_data jsonb, after_data jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE treasury_transactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), transaction_type varchar(20) NOT NULL CHECK (transaction_type IN ('receipt', 'payment')), account_title varchar(160) NOT NULL, bank_or_cash varchar(160) NOT NULL, amount numeric(20,2) NOT NULL CHECK (amount > 0), description varchar(500) NOT NULL, status varchar(20) NOT NULL DEFAULT 'pending', journal_entry_id uuid REFERENCES journal_entries(id), created_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sales_invoices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), invoice_number bigint NOT NULL, customer_name varchar(160) NOT NULL, subtotal numeric(20,2) NOT NULL CHECK (subtotal > 0), discount numeric(20,2) NOT NULL DEFAULT 0, tax numeric(20,2) NOT NULL DEFAULT 0, total numeric(20,2) NOT NULL CHECK (total > 0), status varchar(20) NOT NULL DEFAULT 'draft', journal_entry_id uuid REFERENCES journal_entries(id), created_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (organization_id, invoice_number));
CREATE TABLE sales_invoice_lines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid NOT NULL REFERENCES sales_invoices(id) ON DELETE CASCADE, item_title varchar(200) NOT NULL, quantity numeric(20,3) NOT NULL CHECK (quantity > 0), unit_price numeric(20,2) NOT NULL CHECK (unit_price >= 0), line_total numeric(20,2) NOT NULL CHECK (line_total >= 0));
CREATE TABLE inventory_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), sku varchar(60) NOT NULL, title varchar(200) NOT NULL, unit varchar(30) NOT NULL DEFAULT 'عدد', quantity numeric(20,3) NOT NULL DEFAULT 0, minimum_quantity numeric(20,3) NOT NULL DEFAULT 0, unit_cost numeric(20,2) NOT NULL DEFAULT 0, UNIQUE (organization_id, sku));
CREATE TABLE purchase_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), order_number bigint NOT NULL, supplier_name varchar(160) NOT NULL, total numeric(20,2) NOT NULL CHECK (total > 0), status varchar(20) NOT NULL DEFAULT 'draft', journal_entry_id uuid REFERENCES journal_entries(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (organization_id, order_number));
CREATE TABLE purchase_order_lines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), purchase_order_id uuid NOT NULL REFERENCES purchase_orders(id) ON DELETE CASCADE, item_id uuid REFERENCES inventory_items(id), item_title varchar(200) NOT NULL, quantity numeric(20,3) NOT NULL CHECK (quantity > 0), unit_price numeric(20,2) NOT NULL CHECK (unit_price > 0), line_total numeric(20,2) NOT NULL CHECK (line_total > 0));
CREATE TABLE employees (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), personnel_code varchar(40) NOT NULL, full_name varchar(160) NOT NULL, department varchar(120) NOT NULL, job_title varchar(120) NOT NULL, base_salary numeric(20,2) NOT NULL CHECK (base_salary > 0), is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (organization_id, personnel_code));
CREATE TABLE payroll_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), title varchar(100) NOT NULL, period varchar(30) NOT NULL, gross_total numeric(20,2) NOT NULL, deductions_total numeric(20,2) NOT NULL, net_total numeric(20,2) NOT NULL, status varchar(20) NOT NULL DEFAULT 'draft', journal_entry_id uuid REFERENCES journal_entries(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payslips (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payroll_run_id uuid NOT NULL REFERENCES payroll_runs(id) ON DELETE CASCADE, employee_id uuid NOT NULL REFERENCES employees(id), overtime numeric(20,2) NOT NULL DEFAULT 0, deductions numeric(20,2) NOT NULL DEFAULT 0, gross_amount numeric(20,2) NOT NULL, net_amount numeric(20,2) NOT NULL);
CREATE TABLE fixed_assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), asset_code varchar(50) NOT NULL, title varchar(200) NOT NULL, location varchar(160) NOT NULL, acquisition_cost numeric(20,2) NOT NULL CHECK (acquisition_cost > 0), useful_life_months integer NOT NULL CHECK (useful_life_months > 0), accumulated_depreciation numeric(20,2) NOT NULL DEFAULT 0, status varchar(20) NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (organization_id, asset_code));
CREATE TABLE production_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), order_number bigint NOT NULL, product_title varchar(200) NOT NULL, planned_quantity numeric(20,3) NOT NULL CHECK (planned_quantity > 0), material_cost numeric(20,2) NOT NULL DEFAULT 0, labor_cost numeric(20,2) NOT NULL DEFAULT 0, total_cost numeric(20,2) NOT NULL DEFAULT 0, status varchar(20) NOT NULL DEFAULT 'planned', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (organization_id, order_number));
CREATE TABLE production_materials (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), production_order_id uuid NOT NULL REFERENCES production_orders(id) ON DELETE CASCADE, material_title varchar(200) NOT NULL, quantity numeric(20,3) NOT NULL CHECK (quantity > 0), unit_cost numeric(20,2) NOT NULL CHECK (unit_cost >= 0), line_cost numeric(20,2) NOT NULL CHECK (line_cost >= 0));
CREATE INDEX domain_events_module_created_idx ON domain_events(module, created_at DESC);
CREATE INDEX audit_logs_entity_idx ON audit_logs(entity_type, entity_id, created_at DESC);
CREATE INDEX treasury_transactions_created_idx ON treasury_transactions(created_at DESC);
CREATE INDEX sales_invoices_created_idx ON sales_invoices(created_at DESC);
CREATE INDEX inventory_items_title_idx ON inventory_items(title);
CREATE INDEX purchase_orders_created_idx ON purchase_orders(created_at DESC);
CREATE INDEX employees_department_idx ON employees(department);
CREATE INDEX payroll_runs_created_idx ON payroll_runs(created_at DESC);
CREATE INDEX fixed_assets_created_idx ON fixed_assets(created_at DESC);
CREATE INDEX production_orders_created_idx ON production_orders(created_at DESC);
